    ) AS v(code, name, sort_order);
  END IF;

  IF NOT EXISTS (SELECT 1 FROM company_bottom_template_lines WHERE company_id = p_company_id) THEN
    INSERT INTO company_bottom_template_lines (company_id, name, kind, charge_mode, rate, amount, sort_order)
    VALUES
      (p_company_id, 'GC Fee',        'percent', 'base',  10, NULL, 0),
      (p_company_id, 'GL Insurance',  'percent', 'total',  2, NULL, 1),
      (p_company_id, 'Builders Risk', 'percent', 'base',   1, NULL, 2);
  END IF;
END;
$function$;
REVOKE ALL ON FUNCTION public.seed_company_division_defaults(uuid) FROM PUBLIC, anon, authenticated;
